-- Higher Study monitoring (additive, reversible). NOTE: verificationStatus column
-- defaults for existing tables are application-level (Prisma) — no data is rewritten.
CREATE TABLE "HigherStudyFaculty" ("id" TEXT NOT NULL PRIMARY KEY, "universityId" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL DEFAULT 'faculty', "parentId" TEXT, "officialUrl" TEXT, "sourceUrl" TEXT, "lastVerifiedAt" DATETIME, "verificationStatus" TEXT NOT NULL DEFAULT 'pending-review', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE INDEX "HigherStudyFaculty_universityId_idx" ON "HigherStudyFaculty"("universityId"); CREATE INDEX "HigherStudyFaculty_type_idx" ON "HigherStudyFaculty"("type");
CREATE TABLE "HigherStudyCourseIntake" ("id" TEXT NOT NULL PRIMARY KEY, "courseId" TEXT NOT NULL, "intakeName" TEXT NOT NULL, "academicYear" TEXT, "opensAt" DATETIME, "deadline" DATETIME, "intlDeadline" DATETIME, "scholarshipDeadline" DATETIME, "startsAt" DATETIME, "rolling" BOOLEAN NOT NULL DEFAULT false, "intlConfirmed" BOOLEAN NOT NULL DEFAULT false, "sourceUrl" TEXT, "lastVerifiedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE INDEX "HigherStudyCourseIntake_courseId_idx" ON "HigherStudyCourseIntake"("courseId"); CREATE INDEX "HigherStudyCourseIntake_deadline_idx" ON "HigherStudyCourseIntake"("deadline"); CREATE INDEX "HigherStudyCourseIntake_startsAt_idx" ON "HigherStudyCourseIntake"("startsAt");
CREATE TABLE "HigherStudySourceRecord" ("id" TEXT NOT NULL PRIMARY KEY, "url" TEXT NOT NULL, "owner" TEXT, "sourceType" TEXT NOT NULL DEFAULT 'university-course', "entityType" TEXT, "entityId" TEXT, "countrySlug" TEXT, "title" TEXT, "licenseNote" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "lastCheckedAt" DATETIME, "lastStatus" TEXT, "failCount" INTEGER NOT NULL DEFAULT 0, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "HigherStudySourceRecord_url_key" ON "HigherStudySourceRecord"("url");
CREATE INDEX "HigherStudySourceRecord_entityType_entityId_idx" ON "HigherStudySourceRecord"("entityType", "entityId"); CREATE INDEX "HigherStudySourceRecord_active_idx" ON "HigherStudySourceRecord"("active"); CREATE INDEX "HigherStudySourceRecord_sourceType_idx" ON "HigherStudySourceRecord"("sourceType");
CREATE TABLE "HigherStudySourceSnapshot" ("id" TEXT NOT NULL PRIMARY KEY, "sourceId" TEXT NOT NULL, "contentHash" TEXT NOT NULL, "title" TEXT, "signals" TEXT, "fetchedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "httpStatus" INTEGER);
CREATE INDEX "HigherStudySourceSnapshot_sourceId_fetchedAt_idx" ON "HigherStudySourceSnapshot"("sourceId", "fetchedAt"); CREATE INDEX "HigherStudySourceSnapshot_contentHash_idx" ON "HigherStudySourceSnapshot"("contentHash");
CREATE TABLE "HigherStudyDataChange" ("id" TEXT NOT NULL PRIMARY KEY, "runId" TEXT, "sourceId" TEXT, "entityType" TEXT NOT NULL, "entityId" TEXT, "entityLabel" TEXT, "field" TEXT, "changeType" TEXT NOT NULL, "impact" TEXT NOT NULL DEFAULT 'MEDIUM', "oldValue" TEXT, "newValue" TEXT, "sourceUrl" TEXT, "confidence" REAL NOT NULL DEFAULT 0, "aiSummary" TEXT, "status" TEXT NOT NULL DEFAULT 'pending', "decidedById" TEXT, "decidedAt" DATETIME, "detectedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE INDEX "HigherStudyDataChange_status_idx" ON "HigherStudyDataChange"("status"); CREATE INDEX "HigherStudyDataChange_changeType_idx" ON "HigherStudyDataChange"("changeType"); CREATE INDEX "HigherStudyDataChange_entityType_entityId_idx" ON "HigherStudyDataChange"("entityType", "entityId"); CREATE INDEX "HigherStudyDataChange_detectedAt_idx" ON "HigherStudyDataChange"("detectedAt");
CREATE TABLE "HigherStudyMonitoringRun" ("id" TEXT NOT NULL PRIMARY KEY, "status" TEXT NOT NULL DEFAULT 'running', "sourcesChecked" INTEGER NOT NULL DEFAULT 0, "sourcesFailed" INTEGER NOT NULL DEFAULT 0, "changesDetected" INTEGER NOT NULL DEFAULT 0, "error" TEXT, "startedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" DATETIME, "nextRunAt" DATETIME);
CREATE INDEX "HigherStudyMonitoringRun_status_idx" ON "HigherStudyMonitoringRun"("status"); CREATE INDEX "HigherStudyMonitoringRun_startedAt_idx" ON "HigherStudyMonitoringRun"("startedAt");
CREATE TABLE "HigherStudyOfficialDocument" ("id" TEXT NOT NULL PRIMARY KEY, "title" TEXT NOT NULL, "sourceUrl" TEXT NOT NULL, "universityId" TEXT, "countrySlug" TEXT, "category" TEXT NOT NULL DEFAULT 'guide', "fileHash" TEXT, "version" INTEGER NOT NULL DEFAULT 1, "approvalStatus" TEXT NOT NULL DEFAULT 'pending', "publishedAt" DATETIME, "discoveredAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastCheckedAt" DATETIME);
CREATE UNIQUE INDEX "HigherStudyOfficialDocument_sourceUrl_version_key" ON "HigherStudyOfficialDocument"("sourceUrl", "version");
CREATE INDEX "HigherStudyOfficialDocument_countrySlug_idx" ON "HigherStudyOfficialDocument"("countrySlug"); CREATE INDEX "HigherStudyOfficialDocument_approvalStatus_idx" ON "HigherStudyOfficialDocument"("approvalStatus");
